package com.inteebuild.cableplay;
import android.app.DownloadManager; import android.content.Intent; import android.net.Uri; import android.os.Environment; import android.content.pm.PackageManager; import android.os.Bundle; import android.webkit.ValueCallback; import android.webkit.DownloadListener; import android.webkit.WebView; import android.webkit.WebChromeClient; import android.webkit.WebViewClient; import android.webkit.PermissionRequest; import androidx.appcompat.app.AppCompatActivity;
public class MainActivity extends AppCompatActivity {
  WebView wv; ValueCallback<Uri[]> fileCb;
  private boolean hasAny(String[] perms){ try{ for(String p : perms){ String full="android.permission."+p; if(checkSelfPermission(full)==PackageManager.PERMISSION_GRANTED) return true; } }catch(Exception ignored){} return false; }
  private boolean declared(String p){ try{ String[] d=getPackageManager().getPackageInfo(getPackageName(),PackageManager.GET_PERMISSIONS).requestedPermissions; return d!=null && java.util.Arrays.asList(d).contains("android.permission."+p); }catch(Exception e){ return false; } }
  private String ibFileName(String cd,String u){ try{ if(cd!=null){ int i=cd.indexOf("filename="); if(i>=0){ String n=cd.substring(i+8).trim().replace(String.valueOf('"'),""); if(!n.isEmpty()) return n.replaceAll("[\\/:*?\"<>|]","_"); } } String s=Uri.parse(u).getLastPathSegment(); if(s!=null&&!s.isEmpty()) return s.replaceAll("[\\/:*?\"<>|]","_"); }catch(Exception ignored){} return "download"+System.currentTimeMillis(); }
  @Override protected void onCreate(Bundle b){ super.onCreate(b); wv=new WebView(this); setContentView(wv); wv.getSettings().setJavaScriptEnabled(true); wv.getSettings().setDomStorageEnabled(true); wv.getSettings().setAllowFileAccess(true); wv.getSettings().setMixedContentMode(0); try { wv.addJavascriptInterface(new AudioBridge(this), "InteeAudio"); } catch (Exception ignored) {} wv.setDownloadListener(new DownloadListener(){ public void onDownloadStart(String u,String ua,String cd,String mime,long len){ try{ if(!u.startsWith("http")){ startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse(u))); return; } String nm=ibFileName(cd,u); DownloadManager dm=(DownloadManager)getSystemService(DOWNLOAD_SERVICE); DownloadManager.Request rq=new DownloadManager.Request(Uri.parse(u)); rq.setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED); try{ rq.setDestinationInExternalPublicDir(Environment.DIRECTORY_DOWNLOADS,nm); }catch(Exception ignored){} dm.enqueue(rq); }catch(Exception e){ try{ startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse(u))); }catch(Exception ignored){} } } }); wv.setWebViewClient(new WebViewClient(){ public boolean shouldOverrideUrlLoading(WebView v,String u){ if(u.startsWith("tel:")||u.startsWith("mailto:")||u.startsWith("whatsapp:")){ try{ startActivity(new android.content.Intent(android.content.Intent.ACTION_VIEW, android.net.Uri.parse(u))); return true;}catch(Exception e){} } return false; } public void onPageFinished(WebView v,String u){ try{ java.io.InputStream is=getAssets().open("public/catalog.js"); java.io.BufferedReader br=new java.io.BufferedReader(new java.io.InputStreamReader(is)); StringBuilder sb=new StringBuilder(); String l; while((l=br.readLine())!=null) sb.append(l).append("\n"); br.close(); v.evaluateJavascript(sb.toString(),null);}catch(Exception e){} } }); wv.setWebChromeClient(new WebChromeClient(){ public void onPermissionRequest(final PermissionRequest r){ runOnUiThread(new Runnable(){ public void run(){ try{ String[] res=r.getResources(); java.util.List<String> ok=new java.util.ArrayList<>(); for(String x:res){   } if(!ok.isEmpty()) r.grant(ok.toArray(new String[0])); else r.deny(); }catch(Exception e){ try{r.deny();}catch(Exception ignored){}} }}); } public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,WebChromeClient.FileChooserParams p){ if(fileCb!=null){ try{ fileCb.onReceiveValue(null); }catch(Exception ignored){} } fileCb=cb; try{ Intent i=new Intent(Intent.ACTION_GET_CONTENT); i.addCategory(Intent.CATEGORY_OPENABLE); i.setType("*/*"); String[] mt=p!=null?p.getAcceptTypes():null; if(mt!=null&&mt.length>0&&mt[0]!=null&&!mt[0].isEmpty()&&!mt[0].equals("*/*")) i.putExtra(Intent.EXTRA_MIME_TYPES,mt); if(p!=null&&p.getMode()==WebChromeClient.FileChooserParams.MODE_OPEN_MULTIPLE) i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true); startActivityForResult(Intent.createChooser(i,"Seleccionar archivo"),4102); }catch(Exception e){ fileCb=null; try{ cb.onReceiveValue(null); }catch(Exception ignored){} } return true; } }); try { NativePermissions.requestAll(this); } catch (Exception ignored) {} try { if (android.os.Build.VERSION.SDK_INT >= 26) startForegroundService(new android.content.Intent(this, RadioService.class)); else startService(new android.content.Intent(this, RadioService.class)); } catch (Exception ignored) {} wv.loadUrl("https://www.fctv33.com/"); }
  @Override public void onRequestPermissionsResult(int c,String[] p,int[] r){ super.onRequestPermissionsResult(c,p,r); try{ if(c==NativePermissions.REQ_BATCH) NativePermissions.requestBackground(this); }catch(Exception ignored){} }
  @Override protected void onActivityResult(int c,int d,Intent data){ super.onActivityResult(c,d,data); if(c==4102&&fileCb!=null){ Uri[] out=null; try{ if(d==RESULT_OK&&data!=null){ if(data.getClipData()!=null&&data.getClipData().getItemCount()>0){ int n=data.getClipData().getItemCount(); out=new Uri[n]; for(int i=0;i<n;i++) out[i]=data.getClipData().getItemAt(i).getUri(); } else if(data.getData()!=null){ out=new Uri[]{data.getData()}; } } }catch(Exception ignored){} ValueCallback<Uri[]> cb=fileCb; fileCb=null; try{ cb.onReceiveValue(out); }catch(Exception ignored){} } }
  @Override public void onBackPressed(){ if(wv.canGoBack()) wv.goBack(); else super.onBackPressed(); }
}
